// The field catalogue: the building attributes the engine can query, from a host's catalogue
// file (catalogue format 1.0.0, schemas/catalogue-1.schema.json). The file is generated by the
// catalogue command from the host's field definitions (src/catalogue-generate.ts).
// See docs/decisions/0009-field-catalogue-file-format-and-commands.md.
//
// Also here: how a buildings column's PostgreSQL type maps to a field type, shared by the
// generator, the start-up check and the check command's guard.

import { readFile } from 'node:fs/promises';
import type { Catalogue, CatalogueResponse, Field } from '../schemas/query-engine.d.ts';
import type { Query } from './executor.ts';
import { CATALOGUE_VERSIONS, describeSchemaError, validateCatalogueShape } from './schemas.ts';

export interface FieldCatalogue {
  readonly file: Catalogue;
  /** The field with this key, or undefined. */
  field(key: string): Field | undefined;
  /** The fields grouped by category, in the catalogue's order, for GET /v1/catalogue. */
  grouped(): CatalogueResponse;
}

export type CatalogueResult = { ok: true; catalogue: FieldCatalogue } | { ok: false; problems: string[] };

const FILE_HINT = 'Regenerate it with the engine\'s catalogue command (see docs/host-setup.md).';

/** Reads and checks a catalogue file. Problems name the setting and the catalogue's own keys and types. */
export async function readCatalogueFile(path: string, setting: string): Promise<CatalogueResult> {
  let text: string;
  try {
    text = await readFile(path, 'utf8');
  } catch (error) {
    const code = (error as { code?: unknown }).code;
    return { ok: false, problems: [`${setting} names a file the engine cannot read (${typeof code === 'string' ? code : 'error'}).`] };
  }
  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    return { ok: false, problems: [`The catalogue file named by ${setting} is not valid JSON. ${FILE_HINT}`] };
  }
  return checkCatalogue(value, `The catalogue file named by ${setting}`);
}

/** Checks a parsed catalogue against its schema and for consistency. */
export function checkCatalogue(value: unknown, name: string): CatalogueResult {
  if (!validateCatalogueShape(value)) {
    const version = (value as { formatVersion?: unknown } | null)?.formatVersion;
    if (typeof version === 'string' && !CATALOGUE_VERSIONS.includes(version)) {
      return {
        ok: false,
        problems: [`${name} is in catalogue format ${version}; this engine reads ${CATALOGUE_VERSIONS.join(', ')}. ${FILE_HINT}`],
      };
    }
    const details = (validateCatalogueShape.errors ?? []).slice(0, 5).map(describeSchemaError).join('; ');
    return { ok: false, problems: [`${name} does not follow catalogue format ${CATALOGUE_VERSIONS.join(', ')}: ${details}. ${FILE_HINT}`] };
  }
  const file = value as Catalogue;
  const problems: string[] = [];
  const categories = new Set<string>();
  for (const category of file.categories) {
    if (categories.has(category.key)) problems.push(`${name} lists category ${category.key} twice.`);
    categories.add(category.key);
  }
  const fields = new Map<string, Field>();
  for (const field of file.fields) {
    if (fields.has(field.key)) problems.push(`${name} lists field ${field.key} twice.`);
    fields.set(field.key, field);
    if (!categories.has(field.category)) {
      problems.push(`${name} puts field ${field.key} in category ${field.category}, which it does not list.`);
    }
    if (field.allowedValues !== null) {
      const fits = field.type !== 'boolean' && field.allowedValues.every((allowed) => valueFitsType(allowed, field.type));
      if (!fits) problems.push(`${name} gives field ${field.key} allowed values that are not of its type (${field.type}).`);
    }
  }
  const excluded = new Set<string>();
  for (const { column } of file.excludedColumns) {
    if (excluded.has(column)) problems.push(`${name} excludes column ${column} twice.`);
    if (fields.has(column)) problems.push(`${name} lists ${column} both as a field and as an excluded column.`);
    excluded.add(column);
  }
  if (problems.length > 0) return { ok: false, problems: problems.map((problem) => `${problem} ${FILE_HINT}`) };
  return { ok: true, catalogue: fieldCatalogue(file, fields) };
}

/** Whether `value` is a value of a field type: text, a safe whole number, a finite number, or true/false. */
export function valueFitsType(value: unknown, type: Field['type']): boolean {
  if (type === 'text') return typeof value === 'string';
  if (type === 'boolean') return typeof value === 'boolean';
  if (type === 'integer') return Number.isSafeInteger(value);
  return typeof value === 'number' && Number.isFinite(value);
}

function fieldCatalogue(file: Catalogue, fields: ReadonlyMap<string, Field>): FieldCatalogue {
  const grouped: CatalogueResponse = {
    formatVersion: file.formatVersion,
    categories: file.categories.map((category) => ({
      key: category.key,
      title: category.title,
      fields: file.fields.filter((field) => field.category === category.key),
    })),
  };
  return {
    file,
    field: (key) => fields.get(key),
    grouped: () => grouped,
  };
}

// --- Buildings columns and their field types --------------------------------------------------

export interface BuildingColumn {
  name: string;
  /** The column's type as PostgreSQL writes it, e.g. smallint, text[], construction_materials. */
  declaredType: string;
  /** The element type's name for an array, else the type's name (pg_type.typname). */
  baseType: string;
  /** pg_type.typtype of the base type: b base, e enum, d domain, c composite, ... */
  baseKind: string;
  isArray: boolean;
  /** The default as PostgreSQL writes it, or null. */
  defaultExpression: string | null;
}

/** The columns of the host's public.buildings, in table order. Reads only the system catalogues. */
export async function readBuildingColumns(query: Query): Promise<BuildingColumn[]> {
  const rows = await query<{
    name: string;
    declared_type: string;
    base_type: string;
    base_kind: string;
    is_array: boolean;
    default_expression: string | null;
  }>(
    `SELECT a.attname AS name,
            format_type(a.atttypid, a.atttypmod) AS declared_type,
            COALESCE(e.typname, t.typname) AS base_type,
            COALESCE(e.typtype, t.typtype) AS base_kind,
            e.oid IS NOT NULL AS is_array,
            pg_get_expr(d.adbin, d.adrelid) AS default_expression
       FROM pg_catalog.pg_attribute a
       JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
       LEFT JOIN pg_catalog.pg_type e ON t.typcategory = 'A' AND e.oid = t.typelem
       LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
      WHERE a.attrelid = to_regclass('public.buildings') AND a.attnum > 0 AND NOT a.attisdropped
      ORDER BY a.attnum`,
  );
  return rows.map((row) => ({
    name: row.name,
    declaredType: row.declared_type,
    baseType: row.base_type,
    baseKind: row.base_kind,
    isArray: row.is_array,
    defaultExpression: row.default_expression,
  }));
}

export type ColumnFieldType =
  | { supported: true; type: Field['type']; multiValued: boolean }
  | { supported: false; reason: string };

const TYPE_NAMES: Readonly<Record<string, Field['type']>> = {
  int2: 'integer',
  int4: 'integer',
  int8: 'integer',
  float4: 'number',
  float8: 'number',
  numeric: 'number',
  text: 'text',
  varchar: 'text',
  bpchar: 'text',
  bool: 'boolean',
};

/** The field type a column's values have in plan format 1, or why the column cannot be a field. */
export function columnFieldType(column: BuildingColumn): ColumnFieldType {
  const type = column.baseKind === 'e' ? 'text' : TYPE_NAMES[column.baseType];
  if (type === undefined || (column.baseKind !== 'b' && column.baseKind !== 'e')) {
    return { supported: false, reason: `Its type (${column.declaredType}) cannot be queried in plan format 1.` };
  }
  return { supported: true, type, multiValued: column.isArray };
}

/**
 * Start-up: every catalogue field is a buildings column whose type fits the field's.
 * Problems are plain sentences an operator can act on.
 */
export function checkFieldColumns(catalogue: FieldCatalogue, columns: readonly BuildingColumn[]): string[] {
  const byName = new Map(columns.map((column) => [column.name, column]));
  const problems: string[] = [];
  for (const field of catalogue.file.fields) {
    const column = byName.get(field.key);
    if (column === undefined) {
      problems.push(
        `The catalogue lists the field ${field.key} ("${field.title}"), but public.buildings has no such column. ${FILE_HINT}`,
      );
      continue;
    }
    const actual = columnFieldType(column);
    const kind = (type: Field['type'], multiValued: boolean) => `${multiValued ? 'a list of ' : ''}${type}`;
    if (!actual.supported || actual.type !== field.type || actual.multiValued !== field.multiValued) {
      problems.push(
        `The catalogue says the field ${field.key} holds ${kind(field.type, field.multiValued)}, but the column is ` +
          `${column.declaredType}. ${FILE_HINT}`,
      );
    }
  }
  return problems;
}

/** The check command's guard: every buildings column is a field or excluded, and every exclusion exists. */
export function checkColumnsCovered(catalogue: FieldCatalogue, columns: readonly BuildingColumn[]): string[] {
  const excluded = new Set(catalogue.file.excludedColumns.map((entry) => entry.column));
  const present = new Set(columns.map((column) => column.name));
  const problems: string[] = [];
  for (const column of columns) {
    if (catalogue.field(column.name) === undefined && !excluded.has(column.name)) {
      problems.push(
        `The buildings column ${column.name} is neither a field in the catalogue nor on its exclusion list. ` +
          'Regenerate the catalogue: it becomes a field if your field definitions define it, and is excluded ' +
          'with the reason otherwise (see docs/host-setup.md).',
      );
    }
  }
  for (const column of excluded) {
    if (!present.has(column)) {
      problems.push(`The catalogue excludes the column ${column}, which public.buildings no longer has. ${FILE_HINT}`);
    }
  }
  return problems;
}
